-- Analysis view over the Postgres datasource: one row per trip, zone names joined in. The source timestamps carry a 'Z' but are already New York local time (hourly profile peaks ~18:00, troughs ~04:00), so no tz conversion.
CREATE SCHEMASTORE VIEW trips WITH CONTAINER investigator AS SELECT t.trip_id, CAST(t.pickup_datetime AS TIMESTAMP) AS pickup_ts, CAST(CAST(t.pickup_datetime AS TIMESTAMP) AS DATE) AS pickup_date, hour(CAST(t.pickup_datetime AS TIMESTAMP)) AS pickup_hour, date_format(CAST(t.pickup_datetime AS TIMESTAMP), 'EEEE') AS pickup_dow, t.pickup_location_id, pz.zone AS pickup_zone, pz.borough AS pickup_borough, t.dropoff_location_id, dz.zone AS dropoff_zone, dz.borough AS dropoff_borough, CAST(t.passenger_count AS DOUBLE) AS passengers, CAST(t.trip_distance AS DOUBLE) AS distance_mi, CAST(t.trip_duration_minutes AS DOUBLE) AS duration_min, CAST(t.trip_speed_mph AS DOUBLE) AS speed_mph, CAST(t.fare_amount AS DOUBLE) AS fare_usd, CAST(t.tip_amount AS DOUBLE) AS tip_usd, CAST(t.total_amount AS DOUBLE) AS total_usd, CAST(t.congestion_surcharge AS DOUBLE) AS congestion_surcharge, CAST(t.airport_fee AS DOUBLE) AS airport_fee, t.is_valid_trip FROM nyc_taxi_pg.trips_raw t LEFT JOIN nyc_taxi_pg.zones pz ON t.pickup_location_id = pz.location_id LEFT JOIN nyc_taxi_pg.zones dz ON t.dropoff_location_id = dz.location_id
